pub const XYZ_1931_2DEG_1NM: ConstSpectrum = ConstSpectrum {
    start_nm: 380.0,
    stop_nm: 780.0,
    spacing_nm: 1.0,
    num_channels: 3,
    data: &XYZ_1931_2DEG_1NM_DATA,
};

